implementation.solution:
function doublyBothWays(values) {
  let head = null, tail = null;
  for (const v of values) {
    const node = { value: v, prev: tail, next: null };
    if (tail === null) head = node;
    else tail.next = node;
    tail = node;
  }
  const forwards = [], backwards = [];
  for (let n = head; n !== null; n = n.next) forwards.push(n.value);
  for (let n = tail; n !== null; n = n.prev) backwards.push(n.value);
  return { forwards: forwards, backwards: backwards };
}

